SELECT CASE WHEN c.segment IN ('Corporate', 'SMB') THEN 'tier_1' ELSE 'other' END AS segment_group, c.is_active, MAX(t.amount) AS max_amount, SUM(CASE WHEN t.txn_type = 'REFUND' THEN t.amount ELSE 0 END) AS refund_amount FROM transactions t LEFT JOIN accounts a ON t.account_id = a.id INNER JOIN customers c ON a.customer_id = c.id WHERE a.balance > 48000 GROUP BY CASE WHEN c.segment IN ('Corporate', 'SMB') THEN 'tier_1' ELSE 'other' END, c.is_active ORDER BY 3
